function origin(){return(process.env.ALPHALAB_API_ORIGIN||'http://127.0.0.1:8000').replace(/\/+$/,'')}
async function get(path){const r=await fetch(origin()+path,{headers:{Accept:'application/json'}});if(!r.ok)throw new Error('AlphaLab API '+r.status+': '+await r.text());return r.json()}
async function run(input){if(input.confirm_python_execution!==true)throw new Error('Factor evaluation requires confirm_python_execution=true');const id=String(input.project_id||'').trim(),factor=String(input.factor_id||'').trim();if(!id||!factor)throw new Error('project_id and factor_id are required');const project=await get('/api/strategy/projects/'+encodeURIComponent(id));const revision=Number(input.revision||project.current_revision);const pkg=await get('/api/strategy/projects/'+encodeURIComponent(id)+'/revisions/'+revision);const op=input.operation==='history'?'history':'snapshot';const body=op==='history'?{profile:input.profile||project.profile,start_date:input.start_date,end_date:input.end_date,revision,frequency:input.frequency||'monthly',parameters:input.parameters||{},confirm_python_execution:true}:{profile:input.profile||project.profile,as_of_date:input.as_of_date,revision,parameters:input.parameters||{},confirm_python_execution:true};const response=await fetch(origin()+'/api/strategy/projects/'+encodeURIComponent(id)+'/factors/'+encodeURIComponent(factor)+'/'+op,{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json'},body:JSON.stringify(body)});if(!response.ok)throw new Error('AlphaLab API '+response.status+': '+await response.text());const result=await response.json();if(result.revision!==revision||result.source_sha256!==pkg.source_sha256)throw new Error('Strategy revision changed during factor evaluation');return result}
